def shade(cell, fill):
    tcPr = cell._tc.get_or_add_tcPr()
    shd = OxmlElement('w:shd'); shd.set(qn('w:fill'), fill); tcPr.append(shd)

def borders(cell, color='D9D9D9'):
    tcPr = cell._tc.get_or_add_tcPr(); b = tcPr.first_child_found_in('w:tcBorders')
    if b is None:
        b = OxmlElement('w:tcBorders'); tcPr.append(b)
    for edge in ('top','left','bottom','right','insideH','insideV'):
        tag = 'w:' + edge; el = b.find(qn(tag))
        if el is None: el = OxmlElement(tag); b.append(el)
        el.set(qn('w:val'),'single'); el.set(qn('w:sz'),'4'); el.set(qn('w:space'),'0'); el.set(qn('w:color'),color)

def set_cell_text(cell, text, bold=False, color='000000'):
    cell.text = ''
    p = cell.paragraphs[0]; p.alignment = WD_ALIGN_PARAGRAPH.LEFT
    r = p.add_run(str(text)); r.bold = bold; r.font.name='Times New Roman'; r.font.size=Pt(10); r.font.color.rgb=RGBColor.from_string(color)
    cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
    borders(cell)

def add_page_field(paragraph):
    paragraph.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = paragraph.add_run()
    fld = OxmlElement('w:fldSimple'); fld.set(qn('w:instr'),'PAGE')
    run._r.append(fld)

def add_table(doc, headers, rows, widths=None):
    t = doc.add_table(rows=1, cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.style='Table Grid'
    for i,h in enumerate(headers):
        set_cell_text(t.rows[0].cells[i],h,True,'FFFFFF'); shade(t.rows[0].cells[i],'404040')
    for ri,row in enumerate(rows):
        cells=t.add_row().cells
        for i,val in enumerate(row):
            set_cell_text(cells[i],val)
            if ri%2: shade(cells[i],'F2F2F2')
    if widths:
        for row in t.rows:
            for i,w in enumerate(widths): row.cells[i].width=Cm(w)
    doc.add_paragraph().paragraph_format.space_after=Pt(2)
    return t

def add_para(doc, text, style='Body Text', first=True):
    p=doc.add_paragraph(style=style); p.paragraph_format.first_line_indent=Cm(1.25) if first and style=='Body Text' else Pt(0); p.add_run(text); return p

def add_bullets(doc, items):
    for x in items:
        p=doc.add_paragraph(style='List Bullet'); p.paragraph_format.left_indent=Cm(1.25); p.add_run(x)

def add_code(doc, text):
    for line in text.strip('\n').splitlines():
        p=doc.add_paragraph(style='No Spacing'); p.paragraph_format.left_indent=Cm(1); p.paragraph_format.right_indent=Cm(1)
        r=p.add_run(line); r.font.name='Courier New'; r.font.size=Pt(8.5)

